(() => {
'use strict';
const SUPABASE_URL='https://ahslifnthiwfkmaswjno.supabase.co';
const SUPABASE_KEY='sb_publishable_M4UtzEbCLwMCd9LanFWw5g_5b7-fWda';
const $=(id)=>document.getElementById(id); const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={products:[],cart:JSON.parse(localStorage.getItem('gc-shop-cart')||'[]'),lang:localStorage.getItem('gc-language')||'ckb'};
const sb=window.supabase?.createClient?.(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const money=(n)=>`$${Number(n||0).toFixed(2)}`; const productName=(p)=>state.lang==='en'?p.name:state.lang==='ar'?p.name_ar:p.name_ckb; const productDesc=(p)=>state.lang==='en'?p.description:p.description_ar||p.description_ckb||p.description;
const toast=(text)=>{const el=$('toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)};
const saveCart=()=>{localStorage.setItem('gc-shop-cart',JSON.stringify(state.cart));renderCart();};
const cartTotal=()=>state.cart.reduce((sum,row)=>sum+Number(row.price)*row.quantity,0);
function renderCatalog(){const q=($('productSearch').value||'').trim().toLowerCase(),cat=$('categoryFilter').value;const rows=state.products.filter(p=>(cat==='all'||p.category===cat)&&(!q||[p.name,p.name_ckb,p.name_ar,p.sku].join(' ').toLowerCase().includes(q)));$('catalogStatus').textContent=rows.length?`${rows.length} کاڵا بەردەستە`:'هیچ کاڵایەک نەدۆزرایەوە';$('productGrid').innerHTML=rows.map(p=>`<article class="shop-product"><div class="shop-product-img"><img src="${esc(p.image_url||'/assets/shop/shop-hero-mobile-catalog.png')}" alt="${esc(productName(p))}" loading="lazy"><span class="shop-badge">${esc(p.metadata?.badge||'Available')}</span></div><div class="shop-product-body"><small>${esc(p.sku)} · ${esc(p.category)}</small><h3>${esc(productName(p))}</h3><p>${esc(productDesc(p)||'کاڵای هەڵبژێردراوی Globall Cloud.')}</p><div class="shop-product-foot"><span class="shop-price">${money(p.price_usd)} ${p.compare_at_usd?`<del>${money(p.compare_at_usd)}</del>`:''}</span><button class="shop-add" type="button" data-add="${p.id}">زیادکردن +</button></div></div></article>`).join('');}
function renderCart(){const count=state.cart.reduce((n,x)=>n+x.quantity,0);$('cartCount').textContent=count;$('cartTotal').textContent=money(cartTotal());$('checkoutTotal').textContent=money(cartTotal());$('cartItems').innerHTML=state.cart.length?state.cart.map((r,i)=>`<div class="cart-row"><img src="${esc(r.image_url)}" alt=""><div><h4>${esc(r.name)}</h4><small>${money(r.price)} · ${esc(r.sku)}</small><div class="cart-qty"><button type="button" data-qty="${i}" data-delta="-1">−</button><b>${r.quantity}</b><button type="button" data-qty="${i}" data-delta="1">+</button><button class="cart-remove" type="button" data-remove="${i}">لابردن</button></div></div><strong>${money(r.price*r.quantity)}</strong></div>`).join(''):'<div class="shop-status">Cart ـەکەت بەتاڵە. کاڵایەک زیاد بکە بۆ دەستپێکردن.</div>';}
function openCart(){ $('cartDrawer').classList.add('is-open');$('cartDrawer').setAttribute('aria-hidden','false');} function closeCart(){$('cartDrawer').classList.remove('is-open');$('cartDrawer').setAttribute('aria-hidden','true');}
async function loadCatalog(){try{const {data,error}=await sb.from('shop_products').select('id,sku,slug,name,name_ckb,name_ar,description,description_ckb,description_ar,category,image_url,price_usd,compare_at_usd,inventory_count,reserved_count,featured,metadata').eq('is_active',true).order('featured',{ascending:false}).order('sort_order');if(error)throw error;state.products=data||[];renderCatalog();}catch(e){$('catalogStatus').textContent='catalog بەردەست نییە؛ تکایە دووبارە هەوڵبدەوە.';console.error('[GC shop catalog]',e);}}
async function requireSession(){const {data}=await sb.auth.getSession();if(!data.session){location.href='/dashboard#auth';return null}return data.session;}
async function checkout(event){event.preventDefault();if(!state.cart.length){toast('Cart بەتاڵە');return}const msg=$('checkoutMessage'),button=event.target.querySelector('button[type=submit]');msg.className='shop-form-message';msg.textContent='order نێردراوە…';button.disabled=true;try{const session=await requireSession();if(!session)return;const fd=new FormData(event.target);const items=state.cart.map(x=>({product_id:x.id,quantity:x.quantity}));const {data,error}=await sb.rpc('shop_place_order',{p_items:items,p_customer_name:fd.get('customer_name'),p_customer_phone:fd.get('customer_phone'),p_delivery_address:fd.get('delivery_address'),p_notes:fd.get('notes')||null});if(error)throw error;const order=data?.[0];state.cart=[];saveCart();$('checkoutModal').classList.add('hidden');closeCart();msg.className='shop-form-message success';toast(`Order ـەکەت ${order?.order_number||''} نێردرا`);event.target.reset();showOrders();}catch(e){msg.className='shop-form-message error';msg.textContent=e.message||'ناردنی order سەرکەوتوو نەبوو.';}finally{button.disabled=false;}}
async function showOrders(){const session=await requireSession();if(!session)return;const section=$('orderHistory');section.classList.remove('hidden');section.scrollIntoView({behavior:'smooth',block:'start'});const {data,error}=await sb.from('shop_orders').select('id,order_number,status,total_usd,created_at,shop_order_items(quantity,product_name)').eq('customer_user_id',session.user.id).order('created_at',{ascending:false}).limit(20);if(error){$('ordersList').textContent='مێژوو بەردەست نییە.';return}$('ordersList').innerHTML=data?.length?data.map(o=>`<article class="shop-order"><div><strong>${esc(o.order_number)}</strong><small>${new Date(o.created_at).toLocaleString()} · ${(o.shop_order_items||[]).reduce((n,x)=>n+x.quantity,0)} دانە</small></div><div><strong>${money(o.total_usd)}</strong><span class="shop-order-status">${esc(o.status)}</span></div></article>`).join(''):'<div class="shop-status">هێشتا order ـێکت نییە.</div>';}
function addProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;const row=state.cart.find(x=>x.id===id);if(row)row.quantity=Math.min(99,row.quantity+1);else state.cart.push({id:p.id,sku:p.sku,name:productName(p),price:Number(p.price_usd),image_url:p.image_url,quantity:1});saveCart();toast('کاڵا زیاد کرا بۆ Cart');}
document.addEventListener('click',(e)=>{const add=e.target.closest('[data-add]');if(add){addProduct(add.dataset.add);return}const qty=e.target.closest('[data-qty]');if(qty){const i=Number(qty.dataset.qty);state.cart[i].quantity=Math.max(0,state.cart[i].quantity+Number(qty.dataset.delta));if(!state.cart[i].quantity)state.cart.splice(i,1);saveCart();return}const remove=e.target.closest('[data-remove]');if(remove){state.cart.splice(Number(remove.dataset.remove),1);saveCart();return}if(e.target.closest('[data-cart-close]'))closeCart();});
$('cartOpen').onclick=openCart;$('checkoutOpen').onclick=async()=>{if(!state.cart.length){toast('سەرەتا کاڵا زیاد بکە');return}const session=await requireSession();if(session){$('checkoutModal').classList.remove('hidden');$('checkoutMessage').textContent='';}};$('checkoutClose').onclick=()=>$('checkoutModal').classList.add('hidden');$('shopOrdersBtn').onclick=showOrders;$('ordersClose').onclick=()=>$('orderHistory').classList.add('hidden');$('checkoutForm').addEventListener('submit',checkout);$('productSearch').addEventListener('input',renderCatalog);$('categoryFilter').addEventListener('change',renderCatalog);
window.addEventListener('DOMContentLoaded',()=>{if(!sb){$('catalogStatus').textContent='پەیوەندی بە catalog دروست نەبوو.';return}renderCart();loadCatalog();});
})();
